package export_wit_world

import (
	"fmt"
	"strings"
	"unicode/utf8"

	witTypes "go.bytecodealliance.org/pkg/wit/types"
	"wit_component/ohrats_rc_artifact_cache_cache"
	"wit_component/ohrats_rc_artifact_cache_types"
	"wit_component/ohrats_rc_plugin_service_registry"
	"wit_component/ohrats_rc_plugin_types"
)

const (
	serviceName        = "ohrats:rc-artifact-cache/cache"
	localDigest        = "sha256:3071910d02cb4b93c5bf83d2f04eabbd1b1f25062ca6f161e8f60453c96b1f48"
	meshDigest         = "sha256:917b79b2b68d8dce68c0a52ffffd3fab1b2b3e354fb13136b708d2ce55ed5f97"
	tamperedDigest     = "sha256:5d4553c6b682104be56b7da1ddf97ae3913e29432fb169a13a2310cc861dc36f"
	unauthorizedDigest = "sha256:a266213b292d9bc7c62a79025d8d4e2931e5c17781037bb14a3156ca2c45361e"
	replacementDigest  = "sha256:af0c7881a2c728065860f8e59b3f0da442dcc78476a464a40fa328d23eab3f8f"
	fetchCapacity      = 1024
)

var commandNames = []string{
	"cache-local",
	"cache-fallback",
	"cache-miss",
	"cache-unauthorized",
	"cache-tampered",
	"cache-oversized",
	"cache-priority",
	"cache-replacement",
}

type fetchResult = witTypes.Result[witTypes.Option[ohrats_rc_artifact_cache_types.Artifact], string]

func Descriptor() ohrats_rc_plugin_types.Descriptor {
	commands := make([]ohrats_rc_plugin_types.Command, 0, len(commandNames))
	for _, name := range commandNames {
		commands = append(commands, ohrats_rc_plugin_types.Command{
			Name:    name,
			Summary: "Exercise the artifact cache runtime contract",
			Usage:   "rc " + name,
		})
	}
	return ohrats_rc_plugin_types.Descriptor{
		Id:       "ohrats:artifact-cache-fixture-consumer",
		Version:  "0.1.0",
		Provides: []ohrats_rc_plugin_types.Service{},
		Requires: []ohrats_rc_plugin_types.Requirement{{
			Name:      serviceName,
			Version:   "^0.1",
			Selection: ohrats_rc_plugin_types.Selection_Keyed,
		}},
		Commands: commands,
	}
}

func Activate() witTypes.Result[witTypes.Unit, string] {
	return witTypes.Ok[witTypes.Unit, string](witTypes.Unit{})
}

func Deactivate() {}

func Invoke(command string, args []string) witTypes.Result[uint32, string] {
	switch command {
	case "cache-local":
		artifact, err := fetch("local", localDigest)
		if err != "" {
			return witTypes.Err[uint32, string](err)
		}
		return show("local", artifact)
	case "cache-fallback":
		return fallback(meshDigest)
	case "cache-miss":
		return fallback("sha256:" + strings.Repeat("0", 64))
	case "cache-unauthorized":
		return fallback(unauthorizedDigest)
	case "cache-tampered":
		artifact, err := fetch("local", tamperedDigest)
		if err != "" {
			return witTypes.Err[uint32, string](err)
		}
		return show("local", artifact)
	case "cache-oversized":
		return oversized()
	case "cache-priority":
		return priority()
	case "cache-replacement":
		return replacement()
	default:
		return witTypes.Err[uint32, string](fmt.Sprintf("unsupported command %q", command))
	}
}

func fetch(provider string, digest string) (witTypes.Option[ohrats_rc_artifact_cache_types.Artifact], string) {
	result := ohrats_rc_artifact_cache_cache.Fetch(provider, ohrats_rc_artifact_cache_types.FetchRequest{
		Digest:   digest,
		MaxBytes: fetchCapacity,
	})
	if result.IsErr() {
		return witTypes.None[ohrats_rc_artifact_cache_types.Artifact](), result.Err()
	}
	return result.Ok(), ""
}

func fallback(digest string) witTypes.Result[uint32, string] {
	if artifact, err := fetch("local", digest); err != "" {
		return witTypes.Err[uint32, string](err)
	} else if artifact.IsSome() {
		return show("local", artifact)
	}
	if artifact, err := fetch("mesh", digest); err != "" {
		return witTypes.Err[uint32, string](err)
	} else if artifact.IsSome() {
		return show("mesh", artifact)
	}
	fmt.Println("registry:miss")
	return witTypes.Ok[uint32, string](0)
}

func show(source string, artifact witTypes.Option[ohrats_rc_artifact_cache_types.Artifact]) witTypes.Result[uint32, string] {
	if artifact.IsNone() {
		return witTypes.Err[uint32, string](fmt.Sprintf("%s cache miss", source))
	}
	bytes := artifact.Some().Bytes
	if !utf8.Valid(bytes) {
		return witTypes.Err[uint32, string]("artifact is not UTF-8")
	}
	fmt.Printf("%s:%s\n", source, string(bytes))
	return witTypes.Ok[uint32, string](0)
}

func oversized() witTypes.Result[uint32, string] {
	result := ohrats_rc_artifact_cache_cache.Fetch("local", ohrats_rc_artifact_cache_types.FetchRequest{
		Digest:   localDigest,
		MaxBytes: 48*1024*1024 + 1,
	})
	if result.IsErr() {
		return witTypes.Err[uint32, string](result.Err())
	}
	return witTypes.Err[uint32, string]("oversized cache request was accepted")
}

func priority() witTypes.Result[uint32, string] {
	providers := ohrats_rc_plugin_service_registry.Providers(serviceName, "^0.1")
	if providers.IsErr() {
		return witTypes.Err[uint32, string](providers.Err())
	}
	for _, provider := range providers.Ok() {
		fmt.Printf("%s\t%d\t%s\n", provider.ComponentId, provider.Priority, strings.Join(provider.Keys, ","))
	}
	return witTypes.Ok[uint32, string](0)
}

func replacement() witTypes.Result[uint32, string] {
	artifact, err := fetch("local", replacementDigest)
	if err != "" {
		return witTypes.Err[uint32, string](err)
	}
	if artifact.IsSome() {
		fmt.Println("replacement:hit")
	} else {
		fmt.Println("replacement:miss")
	}
	return witTypes.Ok[uint32, string](0)
}
